[{"order":1,"type":"heading","text":"Event Sourcing and Snapshotting in Design Patterns"},{"order":2,"type":"paragraph","text":"Event Sourcing is an architectural pattern where state changes are stored as a sequence of immutable events. Instead of storing just the current state of a domain object, the system records every state-changing action. Snapshotting is a performance optimization technique used alongside Event Sourcing to avoid replaying thousands of historical events every time an aggregate root is loaded."},{"order":3,"type":"subheading","text":"Core Concepts of Event Sourcing"},{"order":4,"type":"bullet_point","text":"Event Store: An append-only database specifically designed to store events in the exact order they occurred."},{"order":5,"type":"bullet_point","text":"Aggregate: A domain object that handles commands, raises events, and applies events to mutate its internal state."},{"order":6,"type":"bullet_point","text":"Event Replay: The process of rebuilding the current state of an aggregate by sequentially applying all historical events from the event store."},{"order":7,"type":"subheading","text":"The Performance Bottleneck"},{"order":8,"type":"paragraph","text":"As applications mature, aggregates accumulate thousands of events. Replaying all events from the beginning of time upon every request introduces severe latency. This is where Snapshotting becomes essential by persisting the state of an aggregate at a specific version point."},{"order":9,"type":"subheading","text":"Implementation in Python"},{"order":10,"type":"code","text":"class Event:
    def __init__(self, event_type, data):
        self.event_type = event_type
        self.data = data

class AccountAggregate:
    def __init__(self, account_id):
        self.account_id = account_id
        self.balance = 0
        self.version = 0

    def apply(self, event):
        if event.event_type == "Deposited":
            self.balance += event.data["amount"]
        elif event.event_type == "Withdrawn":
            self.balance -= event.data["amount"]
        self.version += 1

    def load_from_history(self, events):
        for event in events:
            self.apply(event)"},{"order":11,"type":"subheading","text":"Adding Snapshotting"},{"order":12,"type":"paragraph","text":"To implement snapshotting, we periodically serialize the aggregate state and save it to a snapshot store along with the current version number. When loading the aggregate, we fetch the latest snapshot and replay only the events that occurred after the snapshot version."},{"order":13,"type":"code","text":"class Snapshot:
    def __init__(self, account_id, balance, version):
        self.account_id = account_id
        self.balance = balance
        self.version = version

def load_aggregate_with_snapshot(account_id, snapshot_store, event_store):
    snapshot = snapshot_store.get_latest(account_id)
    aggregate = AccountAggregate(account_id)

    if snapshot:
        aggregate.balance = snapshot.balance
        aggregate.version = snapshot.version
        events = event_store.get_events_after(account_id, snapshot.version)
    else:
        events = event_store.get_all_events(account_id)

    aggregate.load_from_history(events)
    return aggregate"},{"order":14,"type":"subheading","text":"Best Practices"},{"order":15,"type":"bullet_point","text":"Determine a threshold for snapshot creation, such as every 100 events."},{"order":16,"type":"bullet_point","text":"Store snapshots in a fast, read-optimized data store like Redis or a relational database table."},{"order":17,"type":"bullet_point","text":"Ensure that your event handlers are completely idempotent to avoid inconsistent state replays."}]
